#!/usr/bin/env python3
"""Two playable upper-grade practice presets; preserve all18 earlier presets."""
from pathlib import Path
from collections import Counter
import json,uuid
ROOT=Path(__file__).resolve().parents[3];HERE=Path(__file__).parent
selection=json.loads((ROOT/'Tools/Data/ClassicCards/selection.json').read_text())['cards'];cards={'fm_'+c['sourceId']:c for c in selection};old=json.loads((ROOT/'Tools/Data/Arcana/starter-decks.json').read_text());mono={d['id']:d['cards']for d in old['decks']if d['id'].startswith('mono-')}
def subset(id,kind,count):return [c for c in mono[id]if cards[c]['fields']['Category']==kind][:count]
def newdeck(id,name,desc,leader,first,second,topunits,topspells=(),topitems=()):
 result=subset(first,1,8)+subset(second,1,8)
 count=24-len(topunits);left=(count+1)//2;result+=subset(first,2,left)+subset(second,2,count-left)+list(topunits)
 count=6-len(topspells);left=(count+1)//2;result+=subset(first,3,left)+subset(second,3,count-left)+list(topspells)
 count=4-len(topitems);left=(count+1)//2;result+=subset(first,4,left)+subset(second,4,count-left)+list(topitems)
 assert len(result)==50
 for c,n in Counter(result).items():assert n<=cards[c]['fields']['DeckLimit'],(c,n)
 assert all(c in cards for c in result)
 return dict(id=id,name=name,description=desc,recommendedLeaderId=leader,cards=result,kindCounts=dict(Counter(cards[c]['fields']['Category']for c in result)),unitLevelCounts=dict(Counter(cards[c]['fields']['LV']for c in result if cards[c]['fields']['Category']==2)))
decks=[
 newdeck('premium-grove','상위 등급 · 숲과 금속의 결투','정글의독침수의 강한치명과 투우사의 야수회피를 실제 전투에서 쓰는 50장 연습 덱입니다.','kael','mono-forest','mono-metal',['fm_3061320559','fm_3061320560']),
 newdeck('premium-relic','상위 등급 · 대지와 빛의 유산','유니크 킹핀사이클롭·랜드트랩퍼, 레전드 용의보주와 시크릿 차원의충격파를 담은 50장 연습 덱입니다.','noa','mono-earth','mono-light',['fm_3022820395','fm_5112322069','fm_5112322069'],['fm_15052733622'],['fm_14061841555']),
]
q=lambda s:json.dumps(s,ensure_ascii=False)
lines=['// Generated by Tools/Data/Restoration/generate-premium-decks.py.','namespace FantasyCards.Core','{','    internal static class RestorationStarterDeckData','    {','        internal static StarterDeckDefinition[] Create() => new StarterDeckDefinition[]','        {']
for d in decks:
 lines+=['            new StarterDeckDefinition('+', '.join(q(d[k])for k in('id','name','description','recommendedLeaderId'))+',','                '+', '.join(q(c)for c in d['cards'])+'),']
lines+=['        };','    }','}'];(ROOT/'Games/FantasyCards/Assets/Game/Core/RestorationStarterDeckData.cs').write_text('\n'.join(lines)+'\n')
(HERE/'premium-decks.json').write_text(json.dumps({'revision':'fm-restoration-2026-10-27','preservedDecks':18,'totalDecks':20,'scope':'Two newly authored practice presets using exact original cards; not recovered official product deck lists.','decks':decks},ensure_ascii=False,indent=2)+'\n')
p=ROOT/'Games/FantasyCards/Assets/Game/Core/RestorationStarterDeckData.cs.meta'
if not p.exists():p.write_text('fileFormatVersion: 2\nguid: '+uuid.uuid5(uuid.NAMESPACE_URL,'firstgame/restoration/RestorationStarterDeckData').hex+'\n')
print('Generated2 new playable premium presets; preserved18 stable prior IDs.')
